# Nexty Marketing - Phase 04: Warm Orange UI Redesign
# Run from project root after Phase 01-03.

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$ProjectRoot = (Get-Location).Path
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot (".patch-backups\\phase-04-" + $Timestamp)

function Assert-FileExists {
    param([string]$RelativePath)
    $Path = Join-Path $ProjectRoot $RelativePath
    if (-not (Test-Path -LiteralPath $Path)) {
        throw ("File tidak ditemukan: {0}. Jalankan script dari root project Nexty Marketing." -f $RelativePath)
    }
}

function Assert-Contains {
    param(
        [string]$RelativePath,
        [string]$Pattern,
        [string]$Message
    )
    $Path = Join-Path $ProjectRoot $RelativePath
    $Content = Get-Content -LiteralPath $Path -Raw
    if (-not $Content.Contains($Pattern)) {
        throw $Message
    }
}

function Backup-File {
    param([string]$RelativePath)
    $Source = Join-Path $ProjectRoot $RelativePath
    $Destination = Join-Path $BackupRoot $RelativePath
    $DestinationDir = Split-Path -Parent $Destination
    New-Item -ItemType Directory -Path $DestinationDir -Force | Out-Null
    Copy-Item -LiteralPath $Source -Destination $Destination -Force
}

function Write-Base64File {
    param(
        [string]$RelativePath,
        [string]$Base64Content
    )
    $Path = Join-Path $ProjectRoot $RelativePath
    $Bytes = [Convert]::FromBase64String($Base64Content)
    [IO.File]::WriteAllBytes($Path, $Bytes)
}

Write-Host ""
Write-Host "Nexty Marketing - Phase 04 / Warm Orange UI" -ForegroundColor DarkYellow
Write-Host "Project: $ProjectRoot"
Write-Host ""

$RequiredFiles = @(
    "app/globals.css",
    "components/workspace/sidebar.tsx",
    "components/workspace/dashboard-view.tsx",
    "components/workspace/analytics-view.tsx",
    "components/login-screen.tsx",
    "components/workspace/leads-view.tsx",
    "components/workspace/templates-view.tsx"
)

foreach ($RelativePath in $RequiredFiles) {
    Assert-FileExists $RelativePath
}

# Guard: Phase 03 must already be present.
Assert-Contains "components/workspace/leads-view.tsx" "websiteUrl" "Phase 03 belum terdeteksi. Jalankan phase-03-daily-ux-v2.ps1 terlebih dahulu."
Assert-Contains "components/workspace/templates-view.tsx" "setEditing" "Phase 03 belum terdeteksi pada template UI. Jalankan Phase 03 terlebih dahulu."

# Avoid applying twice.
$CurrentCss = Get-Content -LiteralPath (Join-Path $ProjectRoot "app/globals.css") -Raw
if ($CurrentCss.Contains("--orange: #df682f")) {
    throw "Phase 04 tampaknya sudah terpasang. Script dihentikan agar perubahan tidak ditimpa dua kali."
}

New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null

$ChangedFiles = @(
    "app/globals.css",
    "components/workspace/sidebar.tsx",
    "components/workspace/dashboard-view.tsx",
    "components/workspace/analytics-view.tsx",
    "components/login-screen.tsx"
)

Write-Host "Membuat backup..." -ForegroundColor Cyan
foreach ($RelativePath in $ChangedFiles) {
    Backup-File $RelativePath
}

Write-Host "Menerapkan warm orange design system..." -ForegroundColor Cyan
Write-Base64File "app/globals.css" ""
Write-Base64File "components/workspace/sidebar.tsx" ""
Write-Base64File "components/workspace/dashboard-view.tsx" ""
Write-Base64File "components/workspace/analytics-view.tsx" ""
Write-Base64File "components/login-screen.tsx" ""

Write-Host "Menjalankan post-check..." -ForegroundColor Cyan

$Checks = @(
    @{ File = "app/globals.css"; Pattern = "--orange: #df682f" },
    @{ File = "app/globals.css"; Pattern = ".focus-strip" },
    @{ File = "components/workspace/dashboard-view.tsx"; Pattern = "Pekerjaan berikutnya" },
    @{ File = "components/workspace/dashboard-view.tsx"; Pattern = "maxPipeline" },
    @{ File = "components/workspace/sidebar.tsx"; Pattern = "Marketing Desk" },
    @{ File = "components/workspace/analytics-view.tsx"; Pattern = "Lihat hasil tanpa tenggelam di angka." },
    @{ File = "components/login-screen.tsx"; Pattern = "Follow-up rapi. Kerja tetap ringan." }
)

foreach ($Check in $Checks) {
    $RelativePath = [string]$Check.File
    $Pattern = [string]$Check.Pattern
    $Content = Get-Content -LiteralPath (Join-Path $ProjectRoot $RelativePath) -Raw
    if (-not $Content.Contains($Pattern)) {
        throw ("Post-check gagal pada {0}. Pattern tidak ditemukan: {1}. Backup: {2}" -f $RelativePath, $Pattern, $BackupRoot)
    }
}

$AiNeedles = @(
    "@/lib/ai-template",
    "/api/ai/generate-template",
    "GEMINI_API_KEY",
    "GEMINI_MODEL"
)

foreach ($Needle in $AiNeedles) {
    $Found = Get-ChildItem -LiteralPath $ProjectRoot -Recurse -File -Include *.ts,*.tsx,*.css,*.md,*.example |
        Where-Object { $_.FullName -notlike "*\\node_modules\\*" -and $_.FullName -notlike "*\\.next\\*" -and $_.FullName -notlike "*\\.patch-backups\\*" } |
        Select-String -SimpleMatch $Needle -ErrorAction SilentlyContinue
    if ($Found) {
        throw ("Post-check menemukan referensi AI lama: {0}" -f $Needle)
    }
}

Write-Host ""
Write-Host "Phase 04 berhasil diterapkan." -ForegroundColor Green
Write-Host ("Backup: {0}" -f $BackupRoot) -ForegroundColor DarkGray
Write-Host ""
Write-Host "Yang berubah:" -ForegroundColor Yellow
Write-Host "  - Warm ivory + burnt orange + dark cocoa design tokens"
Write-Host "  - Sidebar lebih compact dan operational"
Write-Host "  - Dashboard punya 3 next-action shortcut"
Write-Host "  - Pipeline bar sekarang merepresentasikan jumlah data"
Write-Host "  - Leads table, drawer, form, follow-up, template, analytics dipoles"
Write-Host "  - Login dibuat lebih editorial dan tidak terasa AI SaaS"
Write-Host "  - Responsive + reduced-motion tetap diperhatikan"
Write-Host ""
Write-Host "Verifikasi berikutnya:" -ForegroundColor Yellow
Write-Host "  npm run lint"
Write-Host "  npm test"
Write-Host "  npm run build"
Write-Host "  npm run dev"
Write-Host ""
